/**
 * Templates: categories (e.g. Plumbers, Restaurants), the templates generated by the AI for each
 * category (saved and reused by any project) and the template chosen by a project.
 *
 * Generating a template does not save it: the UI shows the result, then saves it (possibly after
 * a few regenerations) with POST /template-categories/:cid/templates.
 */
import { Router } from 'express';
import { all, get, run, parseJson } from '../db/index.js';
import { badRequest, notFound, HttpError, LANGUAGES } from '../lib/util.js';
import { createProvider } from '../ai/registry.js';
import { AIError } from '../ai/AIProvider.js';
import { COLOR_KEYS, FONTS, ICONS, LAYOUTS, SPACINGS, WEIGHTS, sanitizeSpec } from '../templates/spec.js';
import { generateTemplateSpec } from '../templates/generate.js';
import { touch } from './projects.js';

const router = Router();

const CATEGORIES_SQL = `
  SELECT c.*,
    (SELECT COUNT(*) FROM site_templates t WHERE t.category_id = c.id) AS template_count,
    (SELECT COUNT(*) FROM projects p JOIN site_templates t ON t.id = p.template_id WHERE t.category_id = c.id) AS project_count
  FROM template_categories c ORDER BY c.name COLLATE NOCASE`;

const TEMPLATES_SQL = `
  SELECT t.*, c.name AS category_name, (SELECT COUNT(*) FROM projects p WHERE p.template_id = t.id) AS used_by
  FROM site_templates t JOIN template_categories c ON c.id = t.category_id`;

const requireCategory = (id) => {
  const row = get('SELECT * FROM template_categories WHERE id = ?', id);
  if (!row) throw notFound('Category');
  return row;
};

function serializeTemplate(row) {
  const { spec_json, ...rest } = row;
  return { ...rest, spec: sanitizeSpec(parseJson(spec_json, {})) };
}

const requireTemplate = (id) => {
  const row = get(`${TEMPLATES_SQL} WHERE t.id = ?`, id);
  if (!row) throw notFound('Template');
  return serializeTemplate(row);
};

/** Category name: trimmed, non-empty, unique (case-insensitive). */
function categoryName(value, exceptId = null) {
  const name = String(value ?? '').trim().slice(0, 80);
  if (!name) throw badRequest('Enter a category name.');
  if (get('SELECT id FROM template_categories WHERE name = ? AND id IS NOT ?', name, exceptId)) throw badRequest(`The category "${name}" already exists.`);
  return name;
}

function templateName(value) {
  const name = String(value ?? '').trim().slice(0, 120);
  if (!name) throw badRequest('Enter a template name.');
  return name;
}

const language = (value) => (LANGUAGES[value] ? value : 'it');

/** Allowed values of a template spec (for the template editor). */
router.get('/template-options', (req, res) => res.json({ fonts: FONTS, icons: ICONS, layouts: LAYOUTS, spacings: SPACINGS, weights: WEIGHTS, colorKeys: COLOR_KEYS }));

// ---------------------------------------------------------------- categories --

router.get('/template-categories', (req, res) => res.json(all(CATEGORIES_SQL)));

router.post('/template-categories', (req, res) => {
  const description = String(req.body?.description ?? '').trim().slice(0, 1000);
  const { lastInsertRowid } = run('INSERT INTO template_categories (name, description) VALUES (?, ?)', categoryName(req.body?.name), description);
  res.status(201).json(all(CATEGORIES_SQL).find((c) => c.id === Number(lastInsertRowid)));
});

router.patch('/template-categories/:cid', (req, res) => {
  const cat = requireCategory(req.params.cid);
  const name = req.body?.name !== undefined ? categoryName(req.body.name, cat.id) : cat.name;
  const description = req.body?.description !== undefined ? String(req.body.description).trim().slice(0, 1000) : cat.description;
  run('UPDATE template_categories SET name = ?, description = ? WHERE id = ?', name, description, cat.id);
  res.json(all(CATEGORIES_SQL).find((c) => c.id === cat.id));
});

/** Delete a category and its templates. Projects that used them must choose another template. */
router.delete('/template-categories/:cid', (req, res) => {
  const cat = requireCategory(req.params.cid);
  run('DELETE FROM template_categories WHERE id = ?', cat.id);
  res.status(204).end();
});

/**
 * Generate a template for the category with the AI (not saved).
 * Body: { providerId, instructions?, language? } -> { spec, tokens, generated_by }
 */
router.post('/template-categories/:cid/templates/generate', async (req, res) => {
  const cat = requireCategory(req.params.cid);
  const row = req.body?.providerId ? get('SELECT * FROM ai_providers WHERE id = ?', Number(req.body.providerId)) : null;
  if (!row) throw badRequest('Select an AI provider (Settings → AI Providers to add one).');
  const provider = createProvider(row);
  try {
    const { spec, tokens } = await generateTemplateSpec(provider, {
      category: cat,
      instructions: String(req.body?.instructions ?? '').slice(0, 2000),
      language: language(req.body?.language),
    });
    res.json({ spec, tokens, generated_by: `${row.name} · ${row.model}` });
  } catch (err) {
    if (err instanceof AIError) throw new HttpError(502, err.message);
    throw err;
  }
});

/** Save a template in the category. Body: { name, spec, instructions?, language?, generated_by?, tokens_used? } */
router.post('/template-categories/:cid/templates', (req, res) => {
  const cat = requireCategory(req.params.cid);
  const b = req.body || {};
  if (!b.spec || typeof b.spec !== 'object') throw badRequest('Generate the template first.');
  const { lastInsertRowid } = run(
    'INSERT INTO site_templates (category_id, name, instructions, language, spec_json, generated_by, tokens_used) VALUES (?, ?, ?, ?, ?, ?, ?)',
    cat.id,
    templateName(b.name),
    String(b.instructions ?? '').slice(0, 2000),
    language(b.language),
    JSON.stringify(sanitizeSpec(b.spec)),
    String(b.generated_by ?? '').slice(0, 200),
    Math.max(0, Math.round(Number(b.tokens_used) || 0))
  );
  res.status(201).json(requireTemplate(lastInsertRowid));
});

// ----------------------------------------------------------------- templates --

/** All saved templates, or the ones of a category (?category=<id>). */
router.get('/templates', (req, res) => {
  const rows = req.query.category
    ? all(`${TEMPLATES_SQL} WHERE t.category_id = ? ORDER BY t.id DESC`, Number(req.query.category))
    : all(`${TEMPLATES_SQL} ORDER BY c.name COLLATE NOCASE, t.id DESC`);
  res.json(rows.map(serializeTemplate));
});

router.get('/templates/:tid', (req, res) => res.json(requireTemplate(req.params.tid)));

/** Rename, edit the design (colors, fonts, layouts, texts) or move to another category. */
router.patch('/templates/:tid', (req, res) => {
  const tpl = requireTemplate(req.params.tid);
  const b = req.body || {};
  const name = b.name !== undefined ? templateName(b.name) : tpl.name;
  const spec = b.spec && typeof b.spec === 'object' ? sanitizeSpec(b.spec) : tpl.spec;
  const categoryId = b.category_id !== undefined ? requireCategory(Number(b.category_id)).id : tpl.category_id;
  run("UPDATE site_templates SET name = ?, spec_json = ?, category_id = ?, updated_at = datetime('now') WHERE id = ?", name, JSON.stringify(spec), categoryId, tpl.id);
  res.json(requireTemplate(tpl.id));
});

router.post('/templates/:tid/duplicate', (req, res) => {
  const tpl = requireTemplate(req.params.tid);
  const { lastInsertRowid } = run(
    'INSERT INTO site_templates (category_id, name, instructions, language, spec_json, generated_by, tokens_used) VALUES (?, ?, ?, ?, ?, ?, 0)',
    tpl.category_id,
    `${tpl.name} (copy)`.slice(0, 120),
    tpl.instructions,
    tpl.language,
    JSON.stringify(tpl.spec),
    tpl.generated_by
  );
  res.status(201).json(requireTemplate(lastInsertRowid));
});

/** Delete a template. Projects that used it must choose another one. */
router.delete('/templates/:tid', (req, res) => {
  const tpl = requireTemplate(req.params.tid);
  run('DELETE FROM site_templates WHERE id = ?', tpl.id);
  res.status(204).end();
});

// ------------------------------------------------------- project <-> template --

router.put('/projects/:id/template', (req, res) => {
  const project = get('SELECT * FROM projects WHERE id = ?', req.params.id);
  if (!project) throw notFound('Project');
  const templateId = req.body?.template_id ? requireTemplate(Number(req.body.template_id)).id : null;
  run('UPDATE projects SET template_id = ? WHERE id = ?', templateId, project.id);
  touch(project.id);
  res.json({ template_id: templateId });
});

export default router;
